"""Typed collaboration contract for persistent-cache responsibilities."""

from __future__ import annotations

from collections.abc import Callable
from contextlib import AbstractContextManager
from pathlib import Path
from typing import Any, Protocol


class CacheContext(Protocol):
    """State and operations shared by cache schema, persistence, and repair."""

    cache_file: Path
    source_fingerprint: dict[str, int | str] | None
    unbound_cache_validator: Callable[[dict[str, Any]], bool] | None
    data: dict[str, Any]
    _modified: bool
    CURRENT_VERSION: str
    LOCK_TIMEOUT_SECONDS: float
    STALE_LOCK_SECONDS: float

    def __init__(
        self,
        cache_file: str | Path,
        source_fingerprint: dict[str, int | str] | None = None,
        unbound_cache_validator: Callable[[dict[str, Any]], bool] | None = None,
    ) -> None: ...

    def _load_cache(self) -> dict[str, Any]: ...

    def _create_empty_cache(self) -> dict[str, Any]: ...

    def _migrate_cache_format(self, data: dict[str, Any]) -> dict[str, Any]: ...

    def _validate_cache_integrity(self, data: dict[str, Any]) -> None: ...

    def validate_and_repair(self) -> dict[str, Any]: ...

    def _check_required_fields(self, report: dict[str, Any]) -> None: ...

    def _check_primary_mappings(self, report: dict[str, Any]) -> None: ...

    def _check_cu_symbol_mappings(self, report: dict[str, Any]) -> None: ...

    def _check_orphaned_entries(self, report: dict[str, Any]) -> None: ...

    def _check_duplicate_definitions(self, report: dict[str, Any]) -> None: ...

    def _get_best_definition(self, symbol_name: str) -> dict[str, Any] | None: ...

    def _get_definition_records(self, symbol_name: str) -> list[dict[str, Any]]: ...

    def get_statistics(self) -> dict[str, Any]: ...

    def save(self) -> None: ...

    def _load_disk_cache_for_comparison(self) -> dict[str, Any]: ...

    def _cache_content_unchanged(self, disk_data: dict[str, Any]) -> bool: ...

    def _atomic_write(self, data: dict[str, Any]) -> None: ...

    def _merge_with_disk(self, disk_data: dict[str, Any]) -> dict[str, Any]: ...

    def _can_merge_disk_data(self, disk_data: dict[str, Any]) -> bool: ...

    def _merge_symbol_maps(self, merged: dict[str, Any]) -> None: ...

    def _merge_definition_records(self, merged: dict[str, Any]) -> None: ...

    @staticmethod
    def _merge_definition_list(
        existing: list[dict[str, Any]], incoming: list[dict[str, Any]]
    ) -> list[dict[str, Any]]: ...

    @staticmethod
    def _select_best_definitions(merged: dict[str, Any]) -> None: ...

    @staticmethod
    def _rebuild_reverse_maps(merged: dict[str, Any]) -> None: ...

    def _exclusive_lock(self) -> AbstractContextManager[None]: ...
